import json,runpy
from pathlib import Path
S=Path(__file__).resolve().parents[1];d=json.loads((S/'data/catalog.json').read_text(encoding='utf8'));n=runpy.run_path(str(S/'work/write_bds_simple.py'))['base'];n.update({'KBAR間隔ex':'所有主要交易、建線時刻及HN時刻判斷先過KBAR相位；被略過的根不執行價格保護。','開始交易時間':'主要作KBAR分鐘相位起點；本版不另外以此限制可交易時窗。','最後交易時間':'核心不使用此截止，實際每天HN判斷後就停止一般交易。','部位管理':'每次首次進場與加碼固定一口，不套用共用金額轉口數；合計部位仍可大於一口。','進場模式':'BD線用固定上下目標；Swift86在空手時追蹤低點反彈／高點回落距離。','多進場比':'BD線基準向上突破或Swift低點反彈的距離，支持點數或%。','空進場比':'基準向下突破或Swift高點回落距離；空進場與多同時改用多進場字串。','空進場與多同':'忽略獨立空距離，空側也使用多進場比換算。','加碼進場點數':'每次有利突破後再加一口的價格距離；一筆即使跳過多格也只加一口，再從實際open重設下一階。','最多進場次數':'空手重新建立一輪的次數上限，與有倉加碼口數不同；加碼不增加已進。','全部進場口數':'全體策略有號淨部位的方向上限，0不限制；多空互抵，不是總曝險。','停損比':'每輪首次入場價加減的固定停損距離；加碼不重設此線，另有損益兩平線與移停。','直接停利點數':'依EntryPointList的未計費持倉點數及部分減碼分攤獲利，除目前口數換成全部出場價格；不是每口相同點數。','啟動移停點數':'上述整組點數達此目標才啟動獲利保護，按目前口數換算成觸價。','移停拉回點數':'整組獲利容許回撤點數，除以目前口數換成價格距離；線價只往有利方向調。','BD線開盤時間':'HHmm必須恰等於通過KBAR的報價才新增當日線；若資料或相位缺少該分鐘，當日不補建。','BD線濾網點':'新線open與啟動中基準距離小於此點數則不新增。','HN判斷時間':'第一筆通過KBAR且HHmm>=此時間時處理隔夜，之後當日不再一般進出或風控。','HN留倉數':'隔夜容許保留的口數；0全部停止，有多口超出時按比例縮減成本帳及部位。','HN獲利比':'單口且選隔天開盤平倉時，需未計費持倉獲利>=當筆價格×此值/100才留倉；多口或繼續策略時不以此門檻拒留。','HN處理方式':'隔天開盤平倉在下一次時刻回退的首筆停策略；繼續策略保留狀態。結算時也據此決定平倉或以HN量平開。'})
a={'summary':'BD線或Swift86突破先進一口，再按有利價格階梯逐筆加碼；以整組持倉點數管理停利、移停與兩平退出，另有減碼隔夜及次日續做。','family':'網格與分批','entry':['通過KBAR的報價HHmm恰等於BD線開盤時間才建基準。新線在當根處理末端新增，下一次分派才開始檢查突破。','BD線模式用基準上下目標；Swift86空手追蹤高低點，低點反彈達距離做多、高點回落達距離做空。首次觸發將基準整組移到實際open，建立一口。','持多再漲到下一加碼價、持空再跌到下一加碼價，各增一口；下一門檻從實際open再加減距離，不補齊跳過的每個格子。同根只許一條空手策略新開，其他已觸發者停止。'],'exit':['有倉先檢查直接停利，再檢查加碼，其後才依序移停、損益兩平、固定停損，最後更新移停線；加碼分支在保護退出前，當根只執行其中一條。','普通停損若未耗盡重進次數，回到空手並可同根再測進場；直停、移停、兩平及已達次數的停損會停止。所有比較及成交使用通過KBAR報價的open。','每日HN第一筆處理是否持倉與多口減碼，之後跳過當日一般交易；可於下次開盤首筆退出或持續策略。結算按HN設定平倉或平舊後以HN留倉數重開。'],'mechanics':['停利／移停點數是各入場點與目前價差加總，搭配部分減碼分攤獲利，再除口數轉成價格。兩平線在多口或先前已啟用時另行建立。','全體容量使用有號淨部位，進場和加碼每次一口，不採共用資金管理。一般報價先把OHLC都覆成open。','開盤與HN首筆以時刻TimeOfDay相對上次是否回退判斷，而不是商品TradeDate；跨午夜資料可能提早重設日內狀態。'],'caveats':['沒有資料末端自動強平迴圈；若仍在倉或等待隔天，回測結尾不會另建平倉。HN之後當日也不再檢查價格停損。','持倉點數門檻不扣滑價，普通停損後重新進場的先前虧損也沒有累加到EntryPointList的本輪門檻；它不等於報表最終淨績效。','結算留倉直接用HN留倉數重開，可能大於原本持有口數；而EntryPoint口數調整只會縮不會補大，價格帳與實際新口數可能不一致。','同根平掉策略後全體容量快照未立刻全面重算；部位上限是淨量且方向分開判斷，不能當成保證總曝險限制。'],'parameterNotes':{pp['name']:n[pp['name']] for pp in next(i for i in d['items'] if i['id']=='SuperBDS/StgBB')['parameters']}}
p=S/'analysis/SuperBDS.json';res=json.loads(p.read_text(encoding='utf8'));res['SuperBDS/StgBB']=a;p.write_text(json.dumps(res,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
p=S/'programs.json';x=json.loads(p.read_text(encoding='utf8'));x['SuperBDS']='以多條價格基準突破為核心，涵蓋每日／週期／事件畫線、ATR距離、只做多、格線跨越、當沖、跳空反手、年度階梯及加碼隔夜。各版本在直停啟用、價格參考、口數計法與末端平倉存在實質差異；包含BDSXv6的隔日接回與指定序號虛擬交易。';p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote BB and SuperBDS overview')
